for rel, extra in EXTRAS.items():
    p=Path(rel)
    html=remove_dup_texts(p.read_text(encoding='utf-8'))
    marker=extra.split('data-mixed-depth="',1)[1].split('"',1)[0]
    if f'data-mixed-depth="{marker}"' not in html:
        html=html.replace('</article>', extra+'</article>', 1)
    p.write_text(html, encoding='utf-8')
    print('extended', rel)
